from functools import wraps

def image_decorator(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        name = args[0]
        with open("images/" + name, "rb") as f:
            return func(f)
    return wrapper

@image_decorator
def img(file):
    # do something with the file object
    pass
```
