Here is some sample C code that should accomplish what you described:
```
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main() {
    // Open the input file
    FILE* input_file = fopen("input.txt", "r");

    if (input_file == NULL) {
        printf("Error: Unable to open input file.\n");
        return 1;
    }

    // Get the size of the buffer
    long int bufsize = 1024 * 1024; // 1 MB

    // Allocate memory for the buffer
    char* buffer = (char*)malloc(bufsize);

    if (buffer == NULL) {
        printf("Error: Unable to allocate memory for buffer.\n");
        fclose(input_file);
        return 1;
    }

    // Read the contents of the file into the buffer
    long int num_bytes = fread(buffer, sizeof(char), bufsize, input_file);

    if (num_bytes == 0) {
        printf("Error: Unable to read any data from input file.\n");
        free(buffer);
        fclose(input_file);
        return 1;
    }

    // Calculate the checksum of the buffer
    unsigned long int checksum = 0;
    for (int i = 0; i < num_bytes; ++i) {
        checksum += buffer[i];
    }

    if (checksum == 0) {
        printf("Buffer is empty.\n");
    } else {
        printf("Checksum: %lu\n", checksum);
    }

    // Save the number of bytes read and the checksum to another file
    FILE* output_file = fopen("output.txt", "w");

    if (output_file == NULL) {
        printf("Error: Unable to open output file.\n");
        free(buffer);
        fclose(input_file);
        return 1;
    }

    // Write the number of bytes read and the checksum to the output file
    fprintf(output_file, "%lu\n", num_bytes);
    fprintf(output_file, "%lu\n", checksum);

    // Close the input and output files
    fclose(input_file);
    fclose(output_file);

    return 0;
}
```
This code first opens the input file using `fopen` with "r" mode, which allows reading the file. It then allocates memory for a buffer using `malloc`, and reads the contents of the file into the buffer using `fread`. The `bufsize` variable is used to specify the size of the buffer in bytes.

The code then calculates the checksum of the buffer using a loop that iterates over each byte in the buffer and adds it to an accumulator variable `checksum`. If the `checksum` is 0, then the buffer is empty.

Finally, the code saves the number of bytes read and the checksum to another file using `fopen` with "w" mode, which allows writing to a file. The `output_file` variable is used to store the pointer to the output file, and the `fprintf` function is used to write the values to the file.

Note that this code assumes that the input file contains text data, and that the checksum should be calculated over the entire contents of the buffer. If the input file contains binary data or the checksum should be calculated over a subset of the buffer, then the code will need to be modified accordingly.']

